public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Initialize a visited array to keep track of which n-tersections have been visited
    boolean[] visited = new boolean[n];

    // Initialize the queue with the starting n-tersection
    Queue<Integer> queue = new LinkedList<>();
    queue.offer(start[0]);

    // Loop until the queue is empty
    while (!queue.isEmpty()) {
        // Get the next n-tersection to visit
        int current = queue.poll();

        // If the current n-tersection is the ending n-tersection, return "can be travelled"
        if (current == end[0]) {
            return "can be travelled";
        }

        // Mark the current n-tersection as visited
        visited[current] = true;

        // Loop through all adjacent n-tersections
        for (int i = 0; i < paths.length; i++) {
            // If the adjacent n-tersection is not visited and is connected to the current n-tersection, add it to the queue
            if (!visited[i] && paths[current][i] == 1) {
                queue.offer(i);
            }
        }
    }

    // If the queue is empty and the ending n-tersection was not reached, return "cannot be travelled"
    return "cannot be travelled";
}

