public int search(int[] nums, int target) {
        int left = 0;
        int right = nums.length - 1;
        while (left <= right) {
            int mid = (left + right) / 2;
            if (nums[mid] == target) {
                return mid;
            }
            if (nums[mid] >= nums[left]) { // left half is sorted
                if (target >= nums[left] && target < nums[mid]) {
                    right = mid - 1;
                } else {
                    left = mid + 1;
                }
            } else { // right half is sorted
                if (target > nums[mid] && target <= nums[right]) {
                    left = mid + 1;
                } else {
                    right = mid - 1;
                }
            }
        }
        return -1;
    }

public double trimMean(int[] arr) {
    double mean = 0;
    int n = arr.length;
    int threshold = n / 20; // 5% of the length of the array

    // Sort the array
    Arrays.sort(arr);

    // Find the sum of the elements excluding the smallest and largest 5%
    for (int i = threshold; i < n - threshold; i++) {
        mean += arr[i];
    }

    // Calculate the mean
    mean /= n - 2 * threshold;

    return mean;
}

public boolean canArrange(int[] arr, int k) {
      if (arr.length % 2 == 1) {
          return false;
      }
      int count = 0;
      Map<Integer, Integer> remainders = new HashMap<>();
      for (int num : arr) {
          int remainder = num % k;
          remainders.put(remainder, remainders.getOrDefault(remainder, 0) + 1);
      }

      for (int remainder : remainders.keySet()) {
          if (remainder == k / 2 && (remainders.get(remainder) & 1) == 1) {
              return false;
          } else if (remainders.get(remainder) < remainders.get(k - remainder)) {
              count += remainders.get(remainder);
          } else {
              count += remainders.get(k - remainder);
          }
      }
      return count == arr.length / 2;
  }

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    // Initialize a 2D array to store the minimum time required to collect all apples
    int[][] dp = new int[n][n];

    // Initialize the root node
    dp[0][0] = 0;

    // Iterate over each node
    for (int i = 1; i < n; i++) {
        // Iterate over each edge connected to the current node
        for (int j = 0; j < edges[i].length; j++) {
            // If the current node has an apple, add the time required to collect it
            if (hasApple[i]) {
                dp[i][j] += 1;
            }

            // Add the time required to move from the current node to the connected node
            dp[i][j] += dp[edges[i][j]][0];
        }
    }

    // Iterate over each edge connected to the root node
    for (int i = 0; i < edges[0].length; i++) {
        // Add the time required to move from the root node to the connected node
        dp[0][i] += dp[edges[0][i]][0];
    }

    // Return the minimum time required to collect all the apples and return to the root node
    return dp[0][n - 1];
}

public static boolean splitArraySameAverage(int[] nums) {
        int sum = 0;
        int n = nums.length;
        for (int i = 0; i < n; i++) {
            sum += nums[i];
        }

        int average = sum / n;

        int[] prefixSums = new int[n + 1];
        for (int i = 1; i <= n; i++) {
            prefixSums[i] = prefixSums[i - 1] + nums[i - 1];
        }

        for (int i = average; i <= sum; i++) {
            if (prefixSums[i - average] != i) {
                return false;
            }
        }

        return true;
    }

public int minCostClimbingStairs(int[] cost) {
    int[] dp = new int[cost.length];
    dp[0] = cost[0];
    dp[1] = cost[1];
    for (int i = 2; i < dp.length; i++) {
        dp[i] = cost[i] + Math.min(dp[i - 1], dp[i - 2]);
    }
    return Math.min(dp[dp.length - 1], dp[dp.length - 2]);
}

