public String makeGood(String s) {
    Stack<Character> stack = new Stack<>();
    for (char c : s.toCharArray()) {
        if (stack.isEmpty()) {
            stack.push(c);
        } else {
            char top = stack.peek();
            if (Math.abs(top - c) == 32) {
                stack.pop();
            } else {
                stack.push(c);
            }
        }
    }
    StringBuilder sb = new StringBuilder();
    while (!stack.isEmpty()) {
        sb.append(stack.pop());
    }
    return sb.reverse().toString();
}

