private static boolean isSteppingNumber(int n) {
        int previousDigit = 10;
        while (n > 0) {
            int currentDigit = n % 10;
            if (Math.abs(previousDigit - currentDigit) != 1) {
                return false;
            }
            previousDigit = currentDigit;
            n /= 10;
        }
        return true;
    }

